import{_ as s,l as o,o as e,c as i,v as t,p as l,x as r,d,i as A,S as p}from"./chunks/framework.InCnrqk-.js";const L=JSON.parse('{"title":"NAND 闪存与 FTL","description":"","frontmatter":{"title":"NAND 闪存与 FTL","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/nand-ftl.md","filePath":"cs/nand-ftl.md","lastUpdated":1789023840000}'),E={name:"cs/nand-ftl.md"};function D(h,a,c,N,T,f){const n=o("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="nand-闪存与-ftl" tabindex="-1">NAND 闪存与 FTL <a class="header-anchor" href="#nand-闪存与-ftl" aria-label="Permalink to &quot;NAND 闪存与 FTL&quot;">​</a></h1><div class="epigraph"><p>NAND 按页编程、按块擦除，不能原地改一个扇区；闪存转换层把逻辑块地址骗成「可覆盖的磁盘」，底下做重映射。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Patterson and Hennessy, Computer Organization and Design (RISC-V)；Open NAND Flash Interface 实践 整理</footer></div><p><a href="/cs/nvm-persistent">上一课</a>的字节持久仍少见。<a href="/cs/flash-memory">闪存对照</a>已区分 NOR/NAND 角色。缺口是 <strong>FTL</strong>（flash translation layer）：主机看见 512B/4KiB 逻辑块，NAND 看见页与擦除块，中间这层表如何维护。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>写页前若块内已有数据，通常不能覆盖：要写到新物理页，旧页标无效，逻辑地址改指新页。块满了再擦除，须先把有效页搬走。缺口不是再讲浮栅，而是这张 <strong>L2P 映射</strong>（页级、块级或混合）以及掉电时映射本身也要持久。</p><p>ONFI/Toggle 是颗粒接口；SSD 控制器跑 FTL，主机走 NVMe/SATA——协议在 PCIe 课后。本课钉介质+FTL。</p><h3 id="ftl-不是文件系统" tabindex="-1">FTL 不是文件系统 <a class="header-anchor" href="#ftl-不是文件系统" aria-label="Permalink to &quot;FTL 不是文件系统&quot;">​</a></h3><p>文件系统也做日志与地址映射，但对象是文件与 inode。FTL 对主机呈现一块平板磁盘。两者叠床架屋（日志文件系统 + FTL）会放大写放大。把 FTL 当 ext4，内核块层职责会错。</p><p><span class="marginnote">Harris 与 Patterson/Hennessy 把闪存当存储层次底层。FTL 是 SSD 教材与厂商实践的核心。本课不抄某开源 FTL 源码结构当标准。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读：查 L2P，向 NAND 发页读（可能多 plane）。写：分配空页、编程、更新 L2P、旧页无效。垃圾回收与磨损在下一课。映射表太大则分级，热页在 SRAM，冷页在 NAND——掉电用超级块日志恢复。</p>',11)),(e(),l(p,null,{default:r(()=>[A(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20LBA%5B%22%E4%B8%BB%E6%9C%BA%E9%80%BB%E8%BE%91%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20FTL%5B%22L2P%20%E6%98%A0%E5%B0%84%22%5D%0A%20%20FTL%20--%3E%20PAGE%5B%22NAND%20%E7%89%A9%E7%90%86%E9%A1%B5%22%5D%0A%20%20PAGE%20--%3E%20ERASE%5B%22%E6%93%A6%E9%99%A4%E4%BB%A5%E5%9D%97%E4%B8%BA%E5%8D%95%E4%BD%8D%22%5D%0A%20%20ERASE%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AGC%20%E4%B8%8E%E7%A3%A8%E6%8D%9F%E5%B9%B6%E8%A1%8C%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>ECC：NAND 原始误码率高，页内强 ECC（BCH/LDPC），与 DRAM SECDED 强度不同，仍属<a href="/cs/soft-error-ecc">软错误</a>家族的介质版。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>SSD 内部并行（多 die、plane）让 FTL 把用户写打到不同通道，类似 DRAM 通道但擦除约束不同。持久内存的字节语义在此不提供。磁盘几何课会对照：HDD 可原地覆盖扇区，无 FTL。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 3D NAND 字线工艺，不把 TLC/QLC 电压阈值当光刻课。不写加密盘的密钥槽细节（可点名存在）。</p><p>后课默认：NAND 不能原地覆盖；FTL 把 LBA 映到物理页并留下无效页给 GC。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NAND：页写块擦；FTL 提供可覆盖的逻辑磁盘。</li><li>L2P 自身要可恢复；与文件系统叠层会写放大。</li><li>下一课并行、回收与磨损。</li><li>出处：Harris and Harris；Patterson and Hennessy, COD；ONFI 实践。</li></ul>',8))])}const _=s(E,[["render",D]]);export{L as __pageData,_ as default};
